-- Generated by npm run tags:seed:build. Do not edit by hand.
--
-- Initial, conservative tag backfill. Existing D1 tags are preserved and the
-- migration is idempotent, so it is safe to retry after an interrupted rollout.
-- Do not reapply it after curator ownership begins; doing so would restore tags
-- that a curator intentionally removed.

DROP TABLE IF EXISTS _tag_catalog_seed_0008;
CREATE TABLE _tag_catalog_seed_0008 (
  scope TEXT NOT NULL CHECK(scope IN ('work', 'performance')),
  id TEXT NOT NULL,
  tags TEXT NOT NULL CHECK(json_valid(tags)),
  PRIMARY KEY (scope, id)
);









































UPDATE works
SET tags = (
  SELECT json_group_array(value)
  FROM (
    SELECT DISTINCT value
    FROM (
      SELECT value FROM json_each(
        CASE WHEN json_valid(works.tags) THEN works.tags ELSE '[]' END
      )
      UNION ALL
      SELECT value FROM json_each((
        SELECT seed.tags
        FROM _tag_catalog_seed_0008 AS seed
        WHERE seed.scope = 'work' AND seed.id = works.id
      ))
    )
    ORDER BY value
  )
),
updated_at = datetime('now')
WHERE EXISTS (
  SELECT 1 FROM _tag_catalog_seed_0008 AS seed
  WHERE seed.scope = 'work' AND seed.id = works.id
);

UPDATE performances
SET tags = (
  SELECT json_group_array(value)
  FROM (
    SELECT DISTINCT value
    FROM (
      SELECT value FROM json_each(
        CASE WHEN json_valid(performances.tags) THEN performances.tags ELSE '[]' END
      )
      UNION ALL
      SELECT value FROM json_each((
        SELECT seed.tags
        FROM _tag_catalog_seed_0008 AS seed
        WHERE seed.scope = 'performance' AND seed.id = performances.id
      ))
    )
    ORDER BY value
  )
),
updated_at = datetime('now')
WHERE EXISTS (
  SELECT 1 FROM _tag_catalog_seed_0008 AS seed
  WHERE seed.scope = 'performance' AND seed.id = performances.id
);

DROP TABLE _tag_catalog_seed_0008;
